def show_images(images):
    # MNIST images are already normalized to [-1, 1], so convert to [0, 1] for display
    images = (images + 1) / 2
    fig, ax = plt.subplots(figsize=(20, 20))
    ax.set_xticks([]); ax.set_yticks([])
    ax.imshow(make_grid(images.detach(), nrow=16).permute(1, 2, 0), cmap='gray')

def show_batch(dl):
    for images, _ in dl:
        show_images(images)
        break
